-1 & -6
\end{array}
\right)^{-1} = \left(
\begin{array}{cc}
-3 & -4 \\
\frac{1}{2} & \frac{1}{2}
\end{array}
\right),
\]

然后计算

\[
\left(
\begin{array}{cc}
1 & 8 \\
-1 & -6
\end{array}
\right)^{-1}
\left(
\begin{array}{cc}
5 & 7 \\
-1 & -3
\end{array}
\right)
\left(
\begin{array}{cc}
2 & 1 \\
3 & 2
\end{array}
\right)^{-1}
= \left(
\begin{array}{cc}
-3 & -4 \\
\frac{1}{2} & \frac{1}{2}
\end{array}
\right)
\left(
\begin{array}{cc}
5 & 7 \\
-1 & -3
\end{array}
\right)
\left(
\begin{array}{cc}
2 & -1 \\
-3 & 2
\end{array}
\right).
\]

计算结果为

\[
= \left(
\begin{array}{cc}
-11 & -9 \\
2 & 2
\end{array}
\right)
\left(
\begin{array}{cc}
2 & -1 \\
-3 & 2
\end{array}
\right)
= \left(
\begin{array}{cc}
5 & -7 \\
-2 & 2
\end{array}
\right).
\]

因此，

\[
A^{-1} = \begin{pmatrix}
2 & -1 & 0 & 0 \\
3 & 2 & 0 & 0 \\
-5 & 7 & -3 & -4 \\
2 & -2 & \frac{1}{2} & \frac{1}{2}
\end{pmatrix}.
\]

\[
